#!/usr/bin/env python3
"""Generates data/knights/kara.json (Knightbook 'A Knight's Tale: Kara' p.3-4, Portrait / Talent / Heroic Arc / Technique sheets, owner-supplied 2026-11-16).
Arc icons read with the 'Knight Tokens and Abilities' legend."""
import json, os
T = lambda token, n=1: {"token": token, "n": n}
H = lambda n: {"res": "Heat", "n": n}
ACT = lambda *a: {"res": "Action", "actions": list(a)}
PR = T("PowerReroll", 1); RED = T("PowerDieRed", 1)
def ex(tok, dep): return {"token": tok, "n": 1, "depletion": dep}
def arc(name, plus, levels, unclear=()): return {"name": name, "plus": plus, "levels": [{"level": i + 1, "options": o} for i, o in enumerate(levels)], "unclear": list(unclear)}
P1 = {"text": "[PowerReroll] 1", "ops": [PR]}
ENV = "sword-with-slash icon read as Envenomed (same icon as Fleischjäger L3)"
PULL = "flame-and-hand icon not identified — not applied"
arcs = [
 arc("Wildling", None, [[[T("Break")], [T("Opening"), T("Reposition")]], [[PR]], [[T("Opening")], [T("Break")]], [[PR, T("Reposition")]], [[RED]], [[T("Break"), T("Opening", 2)]]]),
 arc("Thrill-Seeker", None, [[[T("Break"), T("Hug")], [T("Opening"), T("Hug")]], [[PR], [T("Reposition", 2)]], [[T("Opening"), T("Black")]], [[PR], [T("Break")]], [[RED]], [[T("Black"), T("Opening"), T("Vault")]]]),
 arc("Wilder Errant", P1, [[[T("Black"), T("Reposition")]], [[T("Black"), T("Opening")]], [[PR, T("Reposition")], [T("Closing")]], [[RED]], [[T("Black", 2), T("Reposition")]], [[T("Vault"), T("Opening")]], [[T("Diversion")]]]),
 arc("Kingsguard", {"text": "Attack Re-roll 1", "ops": [T("AttackReroll")]}, [[[T("Opening", 2), T("Reposition")]], [[PR, T("Break")]], [[T("Envenomed"), T("Motivate")]], [[RED]], [[PR], [T("Opening", 2)]], [[T("Envenomed"), T("Reposition")]], [[T("Rouse")]]], [ENV]),
 arc("Oathbreaker", {"text": "Auto-break 2", "ops": [T("AutoBreak", 2)]}, [[[T("PowerReroll", 2), T("Reposition")]], [[T("Black", 2), T("Closing", 2)]], [[RED, T("Reposition", 2)]], [[T("Black"), T("Closing"), T("Vault")]], [[T("Black"), T("Pushback", 2)]], [[T("Closing", 2), T("Provoke")]], [[T("Precise")]]]),
 arc("Steadfast", P1, [[[T("Motivate"), T("Pass", 2), T("Reposition", 2)]], [[T("Unknown"), T("Closing")], [T("GreaterPass"), T("Closing")]], [[T("Motivate", 2), T("Pass", 2), PR]], [[RED, T("GreaterPass", 2)]], [[T("Pass"), T("Closing")], [T("Pass"), T("Reposition", 2)]], [[T("Unknown"), T("GreaterPass")], [T("Rouse")]]], [PULL]),
 arc("Wildwalker", P1, [[[T("Opening"), T("Break")], [T("Opening"), T("Reposition")]], [[T("Opening", 2), T("Hug", 2)]], [[T("Reposition", 2), PR], [T("Reposition", 2), T("Break")]], [[RED]], [[T("Closing"), T("Vault")]], [[T("Closing")], [T("Reposition")]], [[T("Break")], [T("Reposition")]], [[T("Break"), T("Reposition")]]]),
 arc("Knight of the Grand Kingdoms", {"text": "[PowerReroll] 1, +1 [Precision]", "ops": [PR, T("Precision")]}, [[[T("Hope"), T("Closing"), T("Reposition", 2)]], [[T("Hope"), T("Closing"), T("Motivate", 2)]], [[RED, T("Unknown", 2), T("Vault")]], [[T("PowerReroll", 2), T("GreaterPass", 2)]], [[T("Sunder"), T("Hug", 2)]], [[RED, T("Motivate", 2)]], [[T("ImprovedDiversion"), T("Provoke")]], [[T("Power")]]], [PULL]),
]
talents = [
 {"id": "wildling", "name": "Wildling", "tier": "starting", "abilities": [
   {"name": "Unconstrained", "text": "If exactly one space adjacent to you is occupied, gain +1 Precision [Precision]. If all adjacent spaces are empty, gain +2 Precision [Precision] instead.", "ops": [{"op": "unconstrained"}]},
   {"name": "Go with the Flow", "text": "Once per Knight Round, when an Ally moves, you may move 1 space.", "ops": [{"op": "goWithTheFlow"}]}]},
 {"id": "wilder-errant", "name": "Wilder Errant", "tier": "vassal", "abilities": [
   {"name": "I Work Alone", "text": "If you are a Lone Knight, gain +1 Evasion [Evasion]. [JUDICIUM] +2 Evasion [Evasion] instead.", "ops": [{"op": "iWorkAlone"}]},
   {"name": "Doing My Own Thing", "text": "Deploy 2. During Encounters, you may choose which space to position yourself on (do not roll the die).", "ops": [{"op": "talentDeploy", "n": 2}]}]},
 {"id": "kingsguard", "name": "Kingsguard", "tier": "vassal", "abilities": [
   {"name": "Strike as One", "text": "At the start of an Attack, Allies adjacent to the Target provide: 1 Ally: +1 Precision [Precision]. 2 Allies: +1 Precision [Precision], Auto-break 1. 3+ Allies: +1 Precision [Precision], Auto-break 1, Auto-rouse 1.", "ops": [{"op": "strikeAsOne"}]},
   {"name": "Natural Leader", "text": "When you perform a [Move action], an Ally may move 1 space.", "ops": [{"op": "naturalLeader"}]}]},
 {"id": "oathbreaker", "name": "Oathbreaker", "tier": "devil", "abilities": [
   {"name": "Peek at the Devil's Hand", "text": "Start of your turn: Look at the top card of a chosen Mortis deck. You may put it on the bottom of that Mortis deck.", "ops": [{"op": "peekDevilsHand"}]},
   {"name": "Take a Breather", "text": "If you used a [Move action] after a [Combat action], you may unexhaust one of your Gear [Gear] cards.", "ops": [{"op": "takeABreather"}]}]},
 {"id": "steadfast", "name": "Steadfast", "tier": "devil", "abilities": [
   {"name": "Relentless Momentum", "text": "After your Attack Roll, if one or more dice exceeds the Monster's [To Hit] by 2, place 1 Sunder [Sunder] token in the Knight Pool. For each miss gain Auto-hope 1.", "ops": [{"op": "relentlessMomentum"}]},
   {"name": "We Go Together", "text": "You may move diagonally. When an Ally moves during your turn, they may move diagonally. Additionally, for this movement, they may move one extra space.", "ops": [{"op": "weGoTogether"}]}]},
]
def tech(name, unlock, cost, text, depletion, ops, timing, exert, gates=None, gateOps=None, unclear=()):
    return {"name": name, "unlock": unlock, "cost": cost, "text": text, "gates": [{"gate": g, "text": t} for g, t in (gates or [])], "depletion": depletion, "unclear": list(unclear), "ops": ops, "timing": timing, "gateOps": gateOps or {}, "exert": exert}
O = lambda op, **kw: dict(op=op, **kw)
techniques = [
 tech("Second Chance", "Start", [H(1)], "Second Chance.", "discard", [O("secondChance")], "onMortisDraw", ex("Break", "discard"), [("KING", "Superior Chance.")], {"KING": [O("superiorChance")]}),
 tech("Knight Roll", "Start", [H(2)], "[Reaction] Reflex.", "delay", [O("reflex", n=1)], "reaction", ex("Opening", "delay"), [("KING", "[Reaction] Advanced Reflex."), ("DEVIL", "[Reaction] Superior Reflex.")], {"KING": [O("reflex", n=2)], "DEVIL": [O("reflex", n=3)]}),
 tech("Knight Pose", "Start", [H(2)], "Stand up.", "delay", [O("standUp")], "free", ex("Opening", "delay"), [("KING", "Rocksteady.")], {"KING": [O("standUp"), O("rocksteady")]}),
 tech("Like the Wind", "Start", [H(2)], "Gain +1 Speed [Speed] until the end of your turn.", "cooldown", [O("turnSpeed", n=1)], "free", ex("PowerReroll", "cooldown"), [("KING", "+2 [Speed] instead."), ("DRAGON", "+4 [Speed] instead.")], {"KING": [O("turnSpeed", n=2)], "DRAGON": [O("turnSpeed", n=4)]}),
 tech("Sprinting Charge", "Start", [ACT("combat", "move"), H(2)], "Rush.", "cooldown", [O("rush")], "complicated", ex("PowerReroll", "cooldown"), [("KING", "Improved Rush instead."), ("DRAGON", "Additionally gain +1 Speed [Speed] and +1 [Power] for this Rush.")], {"KING": [O("improvedRush")], "DRAGON": [O("rushBoost", speed=1, power=1), O("improvedRush"), O("rushBoostEnd")]}),
 tech("Dodge and Weave", "Investigation 1-2", [H(3)], "Hide. As long as this card is in your Cooldown area and you're Hidden, gain Reinforce 1.", "delay", [O("hideNow")], "free", ex("Opening", "delay"), [("DEVIL", "Advanced Reinforce 1 instead.")], {"DEVIL": [O("hideNow")]}),
 tech("Fleet of Foot", "Investigation 1-3", [H(1)], "[Reaction] When resolving an AI card, if you're not the Target, move up to 3 spaces in a straight line in the same direction as the Monster.", "cooldown", [O("reflex", n=3)], "reaction", ex("PowerReroll", "cooldown"), [("DEVIL", "Up to 5 spaces instead.")], {"DEVIL": [O("reflex", n=5)]}, ["Implemented as a plain reaction move of up to 3 (5) spaces — the 'not the Target / straight line in the Monster's direction' restriction is not enforced"]),
 tech("Picking Your Battles", "Quest: Thrill-Seeker", [H(3)], "Place the top BP card on the bottom of the BP deck. If fighting against Mobs, flip a chosen revealed BP card face down instead.", "cooldown", [O("bpBottomOrFlip")], "free", ex("PowerReroll", "cooldown")),
 tech("Keep on Rolling", "Investigation 2-2", [H(1)], "Tumble or Bypass.", "delay", [O("tumble")], "onCrash", ex("Opening", "delay"), [("DEVIL", "Tumble and Superior Bypass instead.")], unclear=["Only the Tumble half is implemented (used when about to suffer Crash); Bypass / Superior Bypass movement is not"]),
 tech("Survival Hack", "Investigation 2-3", [H(2)], "Unexhaust 1 Weapon Gear [Gear] card.", "delay", [O("unexhaustWeapon")], "free", ex("Opening", "delay"), [("DEVIL", "Unexhaust all Gear [Gear] cards instead.")], {"DEVIL": [O("unexhaustGear", n="all")]}),
 tech("I'll Finish What You Started", "Quest: Wilder Errant", [H(3)], "During the Clear the Knight Pool step of another Knight's attack, remove only half of the tokens from the Knight Pool (rounding up).", "instant", [O("keepHalfPool")], "onOtherClearPool", None, [("DRAGON", "Do not remove any tokens instead.")], {"DRAGON": [O("keepHalfPool", all=True)]}, ["No Exert icon on this card"]),
 tech("Cunning Misdirection", "Quest: Wilder Errant", [H(1)], "During the first ability window, place a Diversion [Diversion] token in the Knight Pool.", "cooldown", [O("poolToken", token="diversion", n=1)], "free", ex("PowerReroll", "cooldown"), [("DRAGON", "An Improved Diversion [Improved Diversion] token instead.")], {"DRAGON": [O("poolToken", token="improvedDiversion", n=1)]}, ["Used as a free action before attacking (the token is in the Pool for the Attack)"]),
 tech("Move Up!", "Quest: Kingsguard", [H(3)], "Motivate 2.", "delay", [O("motivateTotal", n=2)], "free", ex("Opening", "delay"), [("KING", "Motivate 4 instead.")], {"KING": [O("motivateTotal", n=4)]}),
 tech("You Can Do It!", "Quest: Kingsguard", [H(2)], "During the second ability window, gain Rouse 1.", "cooldown", [O("poolToken", token="rouse", n=1)], "free", ex("PowerReroll", "cooldown"), [("DRAGON", "Rouse 2 instead.")], {"DRAGON": [O("poolToken", token="rouse", n=2)]}, ["Used as a free action (Rouse token placed in the Pool)"]),
 tech("Avert a Dire Fate", "Investigation 3-2", [H(2)], "Look at the top AI card, then gain the Priority Target token and turn all Monsters to face you. As long as this card is discarded, gain: \"1 [Heat] Acrobatics (you may Vault instead of suffering Knockdown).\"", "discard", [O("avertFate")], "free", ex("Break", "discard"), unclear=["The 'Acrobatics' ability gained while discarded is not implemented"]),
 tech("Rebuke, Reposition, Retaliate!", "Investigation 3-3", [H(1)], "When you survive a Grave Mortis or Judicium draw, move up to 3 spaces and place 4 Opening [Opening] and/or Break [Break] tokens in the Knight Pool.", "discard", [O("rebuke", n=3, tokens=["opening", "break"])], "onSurvive", ex("Break", "discard"), [("DRAGON", "5 spaces and 4 Closing [Closing] and/or Black [Black] tokens instead.")], {"DRAGON": [O("rebuke", n=5, tokens=["closing", "black"])]}),
 tech("Crusader's Strike", "Quest: Wildwalker", [ACT("combat", "move"), H(1)], "Rush. If you deal a Wound during this Rush, you may [Discard] this card to Devote.", "instant", [O("rush")], "complicated", None, unclear=["Devote is not implemented (Rush only)", "No Exert icon on this card"]),
 tech("Act on Instinct", "Investigation 4-2", [H(2)], "[Reaction] Superior Reflex. When you become the Target of an AI or Signature, immediately return this card to your hand and lose -1 [Heat].", "delay", [O("reflex", n=3)], "reaction", ex("Closing", "delay")),
 tech("Master the Terrain", "Investigation 4-3", [ACT("move"), H(2)], "Perform a [Move action] with Superior Bypass. As long as this card is discarded and you're on an Obstacle, gain +1 Evasion [Evasion].", "discard", [O("moveAction")], "free", ex("Hope", "discard"), unclear=["Superior Bypass (moving through / onto Obstacles) is not implemented — performs a normal move"]),
 tech("Dice with the Devil", "Quest: Oathbreaker", [H(2)], "Immediately perform a [Judicium draw]. You may use this Technique as a free action or as a [Reaction].", "discard", [O("judicium")], "free", ex("Fire", "discard"), unclear=["Reaction use is not implemented (free action only)"]),
 tech("Knight in Shining Armor", "Quest: Oathbreaker", [], "Start of Clash: Deploy 1. Place this card under your Armor [Gear] card. As long as that Armor is unexhausted, gain Soak 2. When an Ally becomes adjacent to you, discard this card, exhaust the Armor it was placed under, and gain +1 [Passion].", "discard", None, "startOfClash", ex("Hope", "discard"), unclear=["Not implemented (Exert only)"]),
 tech("Oath of Valor", "Quest: Steadfast", [H(2)], "When another Knight is about to attack, they gain +2 Precision [Precision] and Precise. Then, place this card in that Knight's hand. This Technique does not count toward the Hand Limit of Knights other than Kara. End of Clash: Return this card to Kara's hand.", "cooldown", [O("oathOfValor")], "onOtherAttack", ex("Closing", "cooldown"), unclear=["The card goes to Kara's Cooldown instead of the other Knight's hand"]),
 tech("Just Like We Practised", "Quest: Steadfast", [], "Every other Knight may gain +1 [Heat] to move 1 space. Then, all non-Knight (and non-Squire) Allies may move 1 space. You may use this Technique as a free action or as a [Reaction].", "delay", [O("practised")], "free", ex("Closing", "delay"), unclear=["Reaction use and non-Knight Allies are not implemented"]),
 tech("Can't Catch Me!", "Investigation 5-2", [H(3)], "When you become the Target of an Attack, set its Evasion Roll difficulty to 8+ (before applying modifiers).", "discard", [O("evasionDifficulty", n=8)], "onTargeted", ex("Hope", "discard"), [("JUDICIUM", "Set to 6+ instead.")]),
 tech("Living Weapon", "Investigation 5-3", [H(2)], "Use this Technique before the Attack Roll. Gain Deadly. After the Attack Roll, for each \"10\" you rolled, gain +1 [Power]. Full Evade: Return this card to your hand.", "cooldown", [O("livingWeapon")], "beforeAttack", ex("PowerReroll", "cooldown"), unclear=["'Full Evade: Return this card to your hand' is not implemented"]),
 tech("Know Thyself", "Quest: Knight of the Grand Kingdoms", [], "Discard any amount of Bane [Bane], Condition, and modifier tokens, and Condition cards you have. Nothing can prevent you from using this Technique.", "discard", [O("knowThyself")], "free", ex("Hope", "discard")),
]
data = {"id": "kara", "name": "Kara",
 "_source": "Knightbook 'A Knight's Tale: Kara' (p.3–4 rules & Knight Setup) + Portrait / Talent / Heroic Arc / Technique sprite sheets (owner-supplied 2026-11-16).",
 "specialRules": {"allies": "Ally means any friendly miniature or standee on the Clash Board — be it Knights, Squires or Princesses — and any tokens placed on the Clash Board by the Party — like Little Ser or Placeholder. Additionally, when Kara uses Motivate X, she may use it on Allies.", "note": "[해석, 확인 필요] 현재 구현에서 Ally = 다른 기사 (토큰·Squire는 미포함)."},
 "setup": {"virtues": {"Bravery": 1, "Tenacity": 1, "Insight": 2}, "rapportBoon": {"text": "Deploy 1.", "note": "Rogue's Path에서 미적용 (Renholder와 동일)."}, "explorationCipher": "**50", "portraits": ["Wildling"], "portrait": "wildling", "talent": "Wildling", "heroicArc": "Wildling", "perilArc": "Wildling",
   "techniques": ["Second Chance", "Knight Roll", "Knight Pose", "Like the Wind", "Sprinting Charge"], "gear": ["Knighves", "Shoddy Pitchfork"], "gearNote": "Knightbook: '1 set of Knighves and the Shoddy Pitchfork (Merchant gear)'."},
 "firstDeath": {"text": "Kara's First Death Special Event: Mark the First Death box on your Knight Sheet. Gain +1 Sigh of the Graal.", "ops": [{"op": "markFirstDeath"}, {"op": "gainSigh", "n": 1}], "note": "[해석, 확인 필요] Fleischritter와 같은 보상으로 처리."},
 "components": {"portraits": 2, "talents": 3, "heroicArcs": 4, "perilArcs": 4, "techniques": 26, "gear": 5},
 "talents": talents, "heroicArcs": arcs, "perilArcsRef": "data/knights/peril_arcs.json → arcs.kara", "techniques": techniques, "missing": [],
 "portraits": [
  {"id": "wildling", "name": "Wildling", "tier": "starting", "classes": ["Wildling"], "powerDie": "red", "cardRefresh": 1, "heatRefresh": 3, "handLimit": 5, "speed": 4, "baneLimit": 4},
  {"id": "wilder-kingsguard", "name": "Wilder Errant / Kingsguard", "tier": "vassal", "classes": ["Wilder Errant", "Kingsguard"], "powerDie": "red", "cardRefresh": 1, "heatRefresh": 4, "handLimit": 6, "speed": 5, "baneLimit": 5},
  {"id": "oathbreaker-steadfast", "name": "Oathbreaker / Steadfast", "tier": "devil", "classes": ["Oathbreaker", "Steadfast"], "powerDie": "red", "powerDice": 2, "cardRefresh": 2, "heatRefresh": 5, "handLimit": 7, "speed": 6, "baneLimit": 6}]}
out = os.path.join(os.path.dirname(__file__), '..', 'data', 'knights', 'kara.json'); json.dump(data, open(out, 'w'), ensure_ascii=False, indent=1); print('wrote kara.json', len(techniques), len(arcs))
